/**
 * Family Tasks: login and family data, kept in a Google Sheet in YOUR Google account.
 * This file is generated by build.py from src/core.js + src/gas.js. Edit those, not this file.
 *
 * Setup (once): see backend/SETUP.md. In short: paste this file into a new Apps Script project,
 * run `setup`, then Deploy > New deployment > Web app (Execute as: Me, Who has access: Anyone).
 */
var MAX_SIGNUPS_PER_DAY = 40;
var MAX_FAILED_LOGINS = 6;   // per username, per 15 minutes
var HASH_ROUNDS = 800;

/*CORE*/

function setup() {
  var props = PropertiesService.getScriptProperties();
  var id = props.getProperty('SHEET'), ss;
  if (id) ss = SpreadsheetApp.openById(id);
  else { ss = SpreadsheetApp.create('Family Tasks Data'); props.setProperty('SHEET', ss.getId()); }
  Object.keys(TABLES).forEach(function (name) {
    var sh = ss.getSheetByName(name);
    if (!sh) sh = ss.insertSheet(name);
    sh.getRange(1, 1, sh.getMaxRows(), Math.max(sh.getMaxColumns(), TABLES[name].length)).setNumberFormat('@');
    sh.getRange(1, 1, 1, TABLES[name].length).setValues([TABLES[name]]).setFontWeight('bold');
    sh.setFrozenRows(1);
  });
  var first = ss.getSheetByName('Sheet1'); if (first && ss.getSheets().length > 1) ss.deleteSheet(first);
  ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === 'dailyCleanup') ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger('dailyCleanup').timeBased().everyDays(1).atHour(3).create();
  Logger.log('Ready. Data sheet: ' + ss.getUrl());
}

function dailyCleanup() { var l = LockService.getScriptLock(); l.waitLock(20000); try { core().A._cleanup(); } finally { l.releaseLock(); } }

function doGet() { return out({ ok: true, app: 'Family Tasks backend' }); }

function doPost(e) {
  var req; try { req = JSON.parse(e.postData.contents || '{}'); } catch (err) { return out({ ok: false, error: 'bad_request' }); }
  var cache = CacheService.getScriptCache();
  var user = String(req.username || '').toLowerCase().slice(0, 40);
  var guarded = req.action === 'login' || req.action === 'resetPassword';
  if (guarded && Number(cache.get('fail_' + user) || 0) >= MAX_FAILED_LOGINS) return out({ ok: false, error: 'too_many_tries' });
  if (req.action === 'signup') {
    var day = 'signups_' + Utilities.formatDate(new Date(), 'UTC', 'yyyyMMdd');
    if (Number(cache.get(day) || 0) >= MAX_SIGNUPS_PER_DAY) return out({ ok: false, error: 'signups_full_today' });
  }
  var c = core();
  if (!c.A[req.action] || req.action.charAt(0) === '_') return out({ ok: false, error: 'unknown_action' });
  var lock = LockService.getScriptLock();
  var readOnly = req.action === 'sync' || req.action === 'me';
  if (!readOnly && !lock.tryLock(20000)) return out({ ok: false, error: 'busy_try_again' });
  try {
    var res = c.A[req.action](req);
    c.flush();
    if (guarded && !res.ok) cache.put('fail_' + user, String(Number(cache.get('fail_' + user) || 0) + 1), 900);
    if (req.action === 'signup' && res.ok) { var d = 'signups_' + Utilities.formatDate(new Date(), 'UTC', 'yyyyMMdd'); cache.put(d, String(Number(cache.get(d) || 0) + 1), 86400); }
    return out(res);
  } catch (err) {
    return out({ ok: false, error: String(err && err.message || err) });
  } finally { if (!readOnly) lock.releaseLock(); }
}

function out(o) { return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON); }

// Sheet-backed table store. Rows are read once per request; changes are written straight away.
function core() {
  var ss = SpreadsheetApp.openById(PropertiesService.getScriptProperties().getProperty('SHEET'));
  var cache = {};
  function sheet(t) { return ss.getSheetByName(t); }
  function load(t) {
    if (cache[t]) return cache[t];
    var sh = sheet(t), n = sh.getLastRow(), cols = TABLES[t];
    // Older sheets: add any new columns to the header row
    if (sh.getLastColumn() < cols.length) { sh.getRange(1, 1, sh.getMaxRows(), cols.length).setNumberFormat('@'); sh.getRange(1, 1, 1, cols.length).setValues([cols]).setFontWeight('bold'); }
    var vals = n > 1 ? sh.getRange(2, 1, n - 1, cols.length).getValues() : [];
    cache[t] = vals.map(function (r) { var o = {}; cols.forEach(function (c, i) { o[c] = r[i] === '' ? '' : String(r[i]); }); return o; });
    return cache[t];
  }
  function toRow(t, o) { return TABLES[t].map(function (c) { return o[c] == null ? '' : String(o[c]); }); }
  var db = {
    all: function (t) { return load(t).slice(); },
    insert: function (t, o) { load(t).push(o); var sh = sheet(t), r = sh.getLastRow() + 1; sh.getRange(r, 1, 1, TABLES[t].length).setNumberFormat('@').setValues([toRow(t, o)]); },
    update: function (t, match, patch) {
      var rows = load(t), sh = sheet(t);
      rows.forEach(function (o, i) {
        if (!match(o)) return;
        Object.keys(patch).forEach(function (k) { o[k] = patch[k]; });
        sh.getRange(i + 2, 1, 1, TABLES[t].length).setValues([toRow(t, o)]);
      });
    },
    remove: function (t, match) {
      var rows = load(t), sh = sheet(t);
      for (var i = rows.length - 1; i >= 0; i--) if (match(rows[i])) { sh.deleteRow(i + 2); rows.splice(i, 1); }
    }
  };
  function hash(salt, pw) {
    var h = salt + ':' + pw;
    for (var i = 0; i < HASH_ROUNDS; i++) {
      h = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, h + salt).map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('');
    }
    return h;
  }
  function rand(n) { var s = ''; while (s.length < n) s += Utilities.getUuid().replace(/-/g, ''); return s.slice(0, n); }
  return { A: makeCore(db, { hash: hash, rand: rand, now: function () { return Date.now(); } }), flush: function () { SpreadsheetApp.flush(); } };
}
